-- Seed: Palm Haven rooms, guests, reservations, reservation_guests, room_notes (synthetic)
-- Target hotel (tenant): Palm Haven Hotel

-- Ensure target hotel exists

-- Seed required hotel-scoped reference data
-- - shifts (AM/PM/Night)
-- - consumables (for consumptions / billing flows)
WITH h AS (
  SELECT id AS hotel_id
  FROM public.hotels
  WHERE name = 'Palm Haven Hotel'
  LIMIT 1
),
shift_rows(name, start_time, end_time) AS (
  VALUES
    ('AM', '06:00'::time, '14:00'::time),
    ('PM', '14:00'::time, '22:00'::time),
    ('Night', '22:00'::time, '06:00'::time)
)
SELECT h.hotel_id, sr.name, sr.start_time, sr.end_time
FROM h
CROSS JOIN shift_rows sr
WHERE NOT EXISTS (
  SELECT 1
  FROM public.shifts s
  WHERE s.hotel_id = h.hotel_id
    AND s.name ILIKE sr.name
);

WITH h AS (
  SELECT id AS hotel_id
  FROM public.hotels
  WHERE name = 'Palm Haven Hotel'
  LIMIT 1
),
consumable_rows(name, category, unit_price, billable) AS (
  VALUES
    ('Mini Bar - Water', 'mini_bar', 5.00::numeric, true),
    ('Mini Bar - Coke', 'mini_bar', 4.00::numeric, true),
    ('Laundry - Shirt', 'laundry', 8.00::numeric, true),
    ('Towels - Extra', 'towels', 0::numeric, false)
)
SELECT h.hotel_id, cr.name, cr.category, cr.unit_price, cr.billable
FROM h
CROSS JOIN consumable_rows cr
WHERE NOT EXISTS (
  SELECT 1
  FROM public.consumables c
  WHERE c.hotel_id = h.hotel_id
    AND c.name = cr.name
    AND c.category = cr.category
);

-- Ensure required columns exist (older dev DBs)
ALTER TABLE public.rooms ADD COLUMN IF NOT EXISTS house_keeping_status TEXT;
ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS promised_time TIME;
CREATE INDEX IF NOT EXISTS idx_rooms_house_keeping_status ON public.rooms(house_keeping_status);

